import {snapshot,probabilities} from './engine.js';
import {simulate} from './simulator.js';
const $=id=>document.getElementById(id);
let catalog,match,minute=0,playing=false,last=0,view='overview';
const svgNS='http://www.w3.org/2000/svg';
function svg(tag,attrs){const el=document.createElementNS(svgNS,tag);for(const [k,v] of Object.entries(attrs))el.setAttribute(k,v);return el;}
function text(id,value){$(id).textContent=value;}
function chartBase(id,w){const root=$(id);root.replaceChildren();for(const y of [20,65,110,155])root.append(svg('line',{x1:5,x2:w-5,y1:y,y2:y,stroke:'#e2e3da','stroke-dasharray':'3 4'}));return root;}
function render(){
 const {events,stats}=snapshot(match,minute),h=stats.home,a=stats.away;
 text('home-score',h.goals);text('away-score',a.goals);
 for(const team of ['home','away']){const goals=events.filter(e=>e.team===team&&e.outcome==='goal');const scorers=new Map();for(const e of goals){if(!scorers.has(e.player))scorers.set(e.player,[]);scorers.get(e.player).push(Math.floor(e.minute)+"′");}text(team+'-scorers',[...scorers].map(([name,times])=>name+' '+times.join(', ')).join(' · ')||'No goals');}
 text('clock',`${String(Math.floor(minute)).padStart(2,'0')}:${String(Math.floor((minute%1)*60)).padStart(2,'0')}`);
 text('phase',minute>=90?'Full time':minute>=45?'Second half':'First half');text('time-label',`${Math.floor(minute)}′ / 90′`);$('timeline').value=minute;
 const metric=(id,left,right)=>{$(id).replaceChildren(document.createTextNode(left+' '),Object.assign(document.createElement('em'),{textContent:'—'}),document.createTextNode(' '+right));};
 metric('xg',h.xg.toFixed(2),a.xg.toFixed(2));const possession=h.complete+a.complete?Math.round(h.complete/(h.complete+a.complete)*100):50;metric('possession',possession+'%',(100-possession)+'%');metric('shots',h.shots,a.shots);
 const completion=s=>s.passes?Math.round(s.complete/s.passes*100)+'%':'—';metric('passes',completion(h),completion(a));text('on-target',`${h.target} — ${a.target} on target`);
 const bar=(id,left,right)=>$(id).style.width=(left+right?left/(left+right)*100:50)+'%';bar('xg-bar',h.xg,a.xg);bar('pos-bar',possession,100-possession);bar('shot-bar',h.shots,a.shots);bar('pass-bar',h.complete,a.complete);
 const p=probabilities(stats,minute,match.rates),rounded=p.map(v=>Math.floor(v*100));let remainder=100-rounded.reduce((x,y)=>x+y,0);const order=p.map((v,i)=>[v*100-rounded[i],i]).sort((x,y)=>y[0]-x[0]);for(let i=0;i<remainder;i++)rounded[order[i][1]]++;
 ['p-home','p-draw','p-away'].forEach((id,i)=>$(id).style.width=p[i]*100+'%');['ph','pd','pa'].forEach((id,i)=>text(id,rounded[i]+'%'));
 const best=p.indexOf(Math.max(...p));text('favorite-label',best===0?match.home+' win':best===1?'Draw':match.away+' win');$('win-prob').replaceChildren(document.createTextNode(rounded[best]),Object.assign(document.createElement('span'),{textContent:'%'}));text('prob-caption',minute>=90?'Full time — simulated result.':'Historical scoring rates, current score & time remaining.');
 const shots=events.filter(e=>e.type==='shot'),filter=$('shot-filter').value;$('shot-dots').replaceChildren();
 for(const e of shots.filter(e=>filter==='all'||e.team===filter||(filter==='goal'&&e.outcome==='goal'))){const dot=svg('circle',{cx:25+e.x*6.3,cy:25+e.y*3.7,r:4+e.xg*15,fill:e.team==='home'?'#78bdda':'#e65d46','fill-opacity':e.outcome==='goal'?1:.65,class:'shot',tabindex:0,role:'button','aria-label':`${e.player}, ${e.minute.toFixed(0)} minutes, ${e.outcome}, ${e.xg.toFixed(2)} xG`});const inspect=()=>text('shot-detail',`${Math.floor(e.minute)}′ · ${e.player} · ${e.outcome} · ${e.xg.toFixed(2)} xG`);dot.addEventListener('click',inspect);dot.addEventListener('keydown',ev=>{if(ev.key==='Enter'||ev.key===' '){ev.preventDefault();inspect();}});if(e.outcome==='goal'){dot.setAttribute('stroke-width',3);dot.setAttribute('stroke','#fff');}$('shot-dots').append(dot);}
 const mom=chartBase('momentum',680);mom.append(svg('line',{x1:5,x2:675,y1:85,y2:85,stroke:'#c9cfc5'}));
 for(let bin=0;bin<18;bin++){const ev=events.filter(e=>e.minute>=bin*5&&e.minute<(bin+1)*5);for(const [idx,team] of ['home','away'].entries()){const threat=ev.filter(e=>e.team===team).reduce((s,e)=>s+(e.type==='shot'?e.xg*40:0.3),0),height=Math.min(63,threat*2);mom.append(svg('rect',{x:9+bin*37,y:idx===0?85-height:87,width:27,height,rx:2,fill:idx===0?'#78bdda':'#e65d46'}));}}
 const chart=chartBase('xg-chart',420),max=Math.max(2,h.xg,a.xg)*1.15;
 for(const team of ['home','away']){let total=0;let d='M 5 155';for(const e of shots.filter(e=>e.team===team)){const x=5+e.minute/90*410;d+=` H ${x} V ${155-(total+=e.xg)/max*140}`;}d+=` H ${5+minute/90*410}`;chart.append(svg('path',{d,fill:'none',stroke:team==='home'?'#78bdda':'#e65d46','stroke-width':2.5}));}
 for(const [root,w] of [[mom,680],[chart,420]]){root.append(svg('line',{x1:5+minute/90*(w-10),x2:5+minute/90*(w-10),y1:5,y2:160,stroke:'#253d30','stroke-width':1,'stroke-dasharray':'3 3',opacity:.5}));}
 const axisLabel=svg('text',{x:8,y:12,fill:'#677269','font-size':10,'font-family':'monospace'});axisLabel.textContent=max.toFixed(1)+' xG';chart.append(axisLabel);
 const eventFilter=$('event-filter').value,rows=events.filter(e=>eventFilter==='all'||e.type===eventFilter||(eventFilter==='goal'&&e.outcome==='goal')).slice().reverse().slice(0,100);$('events').replaceChildren();
 for(const e of rows){const row=document.createElement('tr');for(const [idx,value] of [`${Math.floor(e.minute)}′`,e.outcome==='goal'?'Goal':e.type==='shot'?'Shot':'Pass',match[e.team],e.player,e.outcome,e.xg?e.xg.toFixed(2):'—'].entries()){const td=document.createElement('td');if(idx===1){const span=document.createElement('span');span.className='event-type';span.textContent=value;td.append(span);}else td.textContent=value;row.append(td);}$('events').append(row);}
 if(!rows.length){const row=document.createElement('tr'),td=document.createElement('td');td.colSpan=6;td.textContent='No events yet. Play the replay or move the timeline.';row.append(td);$('events').append(row);}
}
function displayMatch(){for(const team of ['home','away']){const edition=match[team+'_edition'];text(team+'-name',match[team]);text(team+'-vintage',edition.season+' / '+edition.competition_name);text('legend-'+team,match[team]+' '+edition.year);const crest=$(team+'-crest');let fallback=$(team+'-crest-fallback');if(!fallback){fallback=document.createElement('span');fallback.id=team+'-crest-fallback';fallback.className='crest fallback-crest';crest.after(fallback);}fallback.textContent=edition.name.split(/\s+/).map(n=>n[0]).slice(0,3).join('');fallback.setAttribute('aria-label',edition.name+' (crest unavailable)');crest.alt=edition.name+' crest';crest.onload=()=>{crest.hidden=false;fallback.hidden=true;};crest.onerror=()=>{crest.hidden=true;fallback.hidden=false;};crest.hidden=true;fallback.hidden=false;if(edition.crest)crest.src=edition.crest;else crest.removeAttribute('src');}text('projected-goals',`${match.home_edition.year} ${match.home}: ${match.rates.home.toFixed(2)} / ${match.away_edition.year} ${match.away}: ${match.rates.away.toFixed(2)}`);text('match-seed','SEED '+match.seed);text('simulation-label',`${match.home} ${match.home_edition.year} vs ${match.away} ${match.away_edition.year} · ${match.venue==='neutral'?'Neutral ground':'Home advantage'}`);text('shot-detail','Select a simulated shot to inspect its quality and outcome.');render();}
function setPlaying(value){playing=value;text('play',value?'Ⅱ':'▶');$('play').setAttribute('aria-label',value?'Pause replay':'Play replay');}
function frame(now){if(playing&&last){minute=Math.min(90,minute+(now-last)/1000*Number($('speed').value)/3);render();if(minute>=90)setPlaying(false);}last=now;requestAnimationFrame(frame);}
$('play').onclick=()=>{if(!match)return;if(minute>=90)minute=0;setPlaying(!playing);render();};$('reset').onclick=()=>{minute=0;setPlaying(false);render();};$('timeline').oninput=e=>{minute=Number(e.target.value);text('shot-detail','Select a shot to inspect its quality and outcome.');render();};$('shot-filter').onchange=render;$('event-filter').onchange=render;
function changeView(next){view=next;document.querySelectorAll('.nav').forEach(el=>el.classList.toggle('active',el.dataset.view===view));text('breadcrumb',({overview:'Match centre',analysis:'Analysis',events:'Event log',about:'Methodology'})[view]);$('dashboard').hidden=['events','about'].includes(view);$('events-section').hidden=['analysis','about'].includes(view);$('about').hidden=view!=='about';}
document.querySelectorAll('.nav').forEach(el=>el.onclick=()=>changeView(el.dataset.view));$('help').onclick=()=>changeView('about');
const competitions=[['en','Premier League'],['es','La Liga'],['de','Bundesliga'],['it','Serie A'],['fr','Ligue 1'],['wc','World Cup'],['euros','Euros'],['copa','Copa América']];
function option(value,label){return Object.assign(document.createElement('option'),{value:String(value),textContent:label});}
function selected(team){return catalog.teams.find(t=>t.id===$(team+'-team').value);}
function populateYears(team,preferred){const code=$(team+'-competition').value,years=[...new Set(catalog.teams.filter(t=>t.competition===code).map(t=>t.year))].sort((a,b)=>b-a);$(team+'-year').replaceChildren(...years.map(y=>option(y,code==='euros'&&y===2021?'2020 / played 2021':y)));if(years.includes(Number(preferred)))$(team+'-year').value=preferred;populateTeams(team);}
function populateTeams(team,preferred){const code=$(team+'-competition').value,year=Number($(team+'-year').value),query=$(team+'-search').value.trim().toLocaleLowerCase(),current=preferred||$(team+'-team').value;
 const editions=catalog.teams.filter(t=>t.competition===code&&t.year===year&&t.name.toLocaleLowerCase().includes(query)).sort((a,b)=>a.name.localeCompare(b.name));
 $(team+'-team').replaceChildren(...editions.map(t=>option(t.id,t.name)));if(editions.some(t=>t.id===current))$(team+'-team').value=current;
 if(!editions.length)$(team+'-team').append(option('','No matching team'));
 updateHistory(team);updateReady();}
function updateHistory(team){const t=selected(team);if(!t){text(team+'-history','No team found. Clear the search or choose another edition.');return;}const report=catalog.coverage.find(c=>c.competition===t.competition&&c.year===t.year);text(team+'-history',`${t.season} · ${t.played} matches · ${t.gf} scored / ${t.ga} conceded${report?.complete===false?' · PARTIAL SOURCE DATA':''}`);}
function updateReady(){const ready=Boolean(selected('home')&&selected('away'));$('simulate').disabled=!ready;$('rerun').disabled=!ready;}
function chooseEdition(team,edition){$(team+'-competition').value=edition.competition;$(team+'-search').value='';populateYears(team,edition.year);populateTeams(team,edition.id);}
function runMatch(){try{const home=selected('home'),away=selected('away');if(!home||!away)throw new Error('Choose both team editions.');if(!$('seed').value.trim())throw new Error('Enter a random seed.');match=simulate(home,away,{seed:Number($('seed').value),venue:$('venue').value});minute=0;setPlaying(false);displayMatch();$('builder-error').hidden=true;const url=new URL(location.href);url.searchParams.set('home',home.id);url.searchParams.set('away',away.id);url.searchParams.set('seed',match.seed);url.searchParams.set('venue',match.venue);history.replaceState(null,'',url);}catch(e){text('builder-error',e.message);$('builder-error').hidden=false;}}
function preset(name){const definitions={city:[['en',2023,'Manchester City'],['es',2016,'Real Madrid']],nations:[['euros',2012,'Spain'],['wc',2022,'Argentina']],barca:[['es',2011,'Barcelona'],['de',2020,'Bayern Munich']]};for(const [i,team] of ['home','away'].entries()){const [code,year,teamName]=definitions[name][i];const edition=catalog.teams.find(t=>t.competition===code&&t.year===year&&t.name===teamName);if(!edition)throw new Error('Preset unavailable in catalog: '+teamName);chooseEdition(team,edition);}runMatch();}
$('simulate').onclick=runMatch;$('rerun').onclick=()=>{$('seed').value=crypto.getRandomValues(new Uint32Array(1))[0];runMatch();};$('full-time').onclick=()=>{if(!match)return;setPlaying(false);minute=90;render();};
$('export').onclick=()=>{if(!match)return;const {events}=snapshot(match,minute);const columns=['id','minute','team','type','player','outcome','xg'];const csv=[['model',match.model,'seed',match.seed,'venue',match.venue].join(','),['home',match.home,match.home_edition.season,'away',match.away,match.away_edition.season].join(','),columns.join(','),...events.map(e=>columns.map(k=>'"'+String(k==='team'?match[e.team]:e[k]).replaceAll('"','""')+'"').join(','))].join('\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));const link=document.createElement('a');link.href=url;link.download=`jogo-bonito-${match.home_edition.id}-vs-${match.away_edition.id}-${match.seed}.csv`;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
try{const response=await fetch('./catalog.json');if(!response.ok)throw new Error('Unable to load team catalog. Reload to retry.');catalog=await response.json();text('catalog-status',`${catalog.teams.length.toLocaleString()} team editions · five leagues + three international tournaments · results through ${catalog.as_of}`);
 for(const team of ['home','away']){$(team+'-competition').replaceChildren(...competitions.map(([code,name])=>option(code,name)));$(team+'-competition').onchange=()=>{$(team+'-search').value='';populateYears(team);};$(team+'-year').onchange=()=>populateTeams(team);$(team+'-search').oninput=()=>populateTeams(team);$(team+'-team').onchange=()=>{updateHistory(team);updateReady();};}
 document.querySelectorAll('[data-preset]').forEach(button=>button.onclick=()=>preset(button.dataset.preset));
 const partial=catalog.coverage.filter(c=>c.complete===false);text('coverage-summary',`${catalog.teams.length.toLocaleString()} team editions from ${catalog.coverage.length} competition editions and ${catalog.coverage.reduce((n,c)=>n+c.matches,0).toLocaleString()} results. Snapshot cutoff: ${catalog.as_of}. ${partial.length} editions have incomplete source results; their available teams remain selectable and are marked in the builder. International result scores can include extra time, so those strengths are approximate 90-minute rates.`);
 for(const c of catalog.coverage){const row=document.createElement('tr');for(const value of [c.label,c.season,c.teams,`${c.matches}${c.expected_matches?' / '+c.expected_matches:''}`,c.complete===true?'Complete':c.complete===false?'Partial':'Unverified']){const td=document.createElement('td');td.textContent=value;row.append(td);}$('coverage-table').append(row);}
 const params=new URLSearchParams(location.search),home=catalog.teams.find(t=>t.id===params.get('home')),away=catalog.teams.find(t=>t.id===params.get('away'));
 if(home&&away){chooseEdition('home',home);chooseEdition('away',away);$('seed').value=params.get('seed')??202316;$('venue').value=['home','neutral'].includes(params.get('venue'))?params.get('venue'):'neutral';runMatch();}else preset('city');
 requestAnimationFrame(frame);
}catch(error){text('catalog-status',error.message);text('phase','Simulator unavailable');$('play').disabled=true;text('builder-error',error.message);$('builder-error').hidden=false;}
